import { parseAddr, toAddr } from "./addr.mjs";

const NUM_RE = /(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/y;
const REF_RE = /\$?[A-Za-z]{1,3}\$?[1-9]\d*(?![A-Za-z0-9_.(])/y;
const NAME_RE = /[A-Za-z_][A-Za-z0-9_.]*/y;
const OP_RE = /<>|<=|>=|[=<>&+\-*\/^(),:]/y;

function match(re, text, i) {
  re.lastIndex = i;
  const m = re.exec(text);
  return m ? m[0] : null;
}

function tokenize(text) {
  const toks = [];
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (/\s/.test(ch)) { i++; continue; }
    let s;
    if (ch === '"') {
      let j = i + 1, v = "";
      for (;;) {
        if (j >= text.length) throw new SyntaxError("unterminated string");
        if (text[j] === '"') {
          if (text[j + 1] === '"') { v += '"'; j += 2; continue; }
          break;
        }
        v += text[j++];
      }
      toks.push({ k: "str", v });
      i = j + 1;
    } else if ((s = match(NUM_RE, text, i))) {
      toks.push({ k: "num", v: Number(s) });
      i += s.length;
    } else if ((s = match(REF_RE, text, i))) {
      toks.push({ k: "ref", v: s });
      i += s.length;
    } else if ((s = match(NAME_RE, text, i))) {
      toks.push({ k: "name", v: s });
      i += s.length;
    } else if ((s = match(OP_RE, text, i))) {
      toks.push({ k: "op", v: s });
      i += s.length;
    } else throw new SyntaxError(`unexpected character '${ch}'`);
  }
  return toks;
}

const normAddr = (s) => s.replace(/\$/g, "").toUpperCase();

/** Parse formula text (without the leading `=`) into an AST. Throws SyntaxError on bad syntax. */
export function parseFormula(text) {
  const toks = tokenize(String(text));
  let p = 0;
  const peek = () => toks[p];
  const isOp = (v) => toks[p]?.k === "op" && toks[p].v === v;
  const expect = (v) => {
    if (!isOp(v)) throw new SyntaxError(`expected '${v}'`);
    p++;
  };
  const levels = [["=", "<>", "<", ">", "<=", ">="], ["&"], ["+", "-"], ["*", "/"], ["^"]];

  function binary(level) {
    if (level === levels.length) return unary();
    let l = binary(level + 1);
    while (peek()?.k === "op" && levels[level].includes(peek().v)) {
      const op = toks[p++].v;
      l = { t: "bin", op, l, r: binary(level + 1) };
    }
    return l;
  }
  function unary() {
    if (isOp("-") || isOp("+")) {
      const op = toks[p++].v;
      return { t: "un", op, x: unary() };
    }
    return primary();
  }
  function primary() {
    const tok = toks[p++];
    if (!tok) throw new SyntaxError("unexpected end of formula");
    if (tok.k === "num") return { t: "num", v: tok.v };
    if (tok.k === "str") return { t: "str", v: tok.v };
    if (tok.k === "ref") {
      const from = normAddr(tok.v);
      if (isOp(":")) {
        p++;
        const r = toks[p++];
        if (r?.k !== "ref") throw new SyntaxError("bad range");
        return { t: "range", from, to: normAddr(r.v) };
      }
      return { t: "ref", addr: from };
    }
    if (tok.k === "name") {
      const up = tok.v.toUpperCase();
      if (isOp("(")) {
        p++;
        const args = [];
        if (!isOp(")")) {
          for (;;) {
            args.push(binary(0));
            if (isOp(",")) { p++; continue; }
            break;
          }
        }
        expect(")");
        return { t: "call", name: up, args };
      }
      if (up === "TRUE" || up === "FALSE") return { t: "bool", v: up === "TRUE" };
      throw new SyntaxError(`unexpected name '${tok.v}'`);
    }
    if (tok.v === "(") {
      const e = binary(0);
      expect(")");
      return e;
    }
    throw new SyntaxError(`unexpected '${tok.v}'`);
  }

  const ast = binary(0);
  if (p < toks.length) throw new SyntaxError(`unexpected '${toks[p].v}'`);
  return ast;
}

function rangeAddrs(from, to) {
  const a = parseAddr(from), b = parseAddr(to);
  const out = [];
  for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++)
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) out.push(toAddr(c, r));
  return out;
}

/** Normalized cell addresses the formula reads, ranges expanded row by row, each once, in order of first appearance. */
export function refsOf(ast) {
  const seen = new Set();
  (function walk(n) {
    switch (n.t) {
      case "ref": seen.add(n.addr); break;
      case "range": for (const a of rangeAddrs(n.from, n.to)) seen.add(a); break;
      case "un": walk(n.x); break;
      case "bin": walk(n.l); walk(n.r); break;
      case "call": n.args.forEach(walk); break;
    }
  })(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const DEC_RE = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null) return 0;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "number") return v;
  const s = v.trim();
  if (s !== "" && DEC_RE.test(s)) return Number(s);
  return "#VALUE!";
}

function toText(v) {
  if (v === null) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null) return false;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "boolean") return v;
  const u = v.trim().toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  return "#VALUE!";
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null && b === null) { a = 0; b = 0; }
  else if (a === null) a = typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  else if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

function roundHalfAway(x, d) {
  d = Math.trunc(d);
  const abs = Math.abs(x);
  const [m, e] = abs.toExponential().split("e");
  const shifted = Math.round(Number(`${m}e${Number(e) + d}`));
  const [m2, e2] = shifted.toExponential().split("e");
  const r = Number(`${m2}e${Number(e2) - d}`);
  return (x < 0 ? -r : r) + 0;
}

const finite = (n) => (Number.isFinite(n) ? n : "#NUM!");

/** Evaluate an AST; `lookup(addr)` returns a cell's value (null if empty). */
export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.t) {
      case "num": case "str": case "bool": return n.v;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "un": {
        const x = toNum(ev(n.x));
        if (isErr(x)) return x;
        return n.op === "-" ? finite(-x + 0) : x;
      }
      case "bin": return binop(n);
      case "call": return call(n);
    }
  };

  function binop(n) {
    const l = ev(n.l), r = ev(n.r);
    if (isErr(l)) return l;
    if (isErr(r)) return r;
    switch (n.op) {
      case "&": return toText(l) + toText(r);
      case "=": return compare(l, r) === 0;
      case "<>": return compare(l, r) !== 0;
      case "<": return compare(l, r) < 0;
      case ">": return compare(l, r) > 0;
      case "<=": return compare(l, r) <= 0;
      case ">=": return compare(l, r) >= 0;
    }
    const a = toNum(l);
    if (isErr(a)) return a;
    const b = toNum(r);
    if (isErr(b)) return b;
    switch (n.op) {
      case "+": return finite(a + b);
      case "-": return finite(a - b);
      case "*": return finite(a * b);
      case "/": return b === 0 ? "#DIV/0!" : finite(a / b);
      case "^": return finite(a ** b);
    }
  }

  // Calls fn(value) for each argument value; ranges expand row by row. Returns an error to stop early.
  function eachArg(args, onRange, onDirect) {
    for (const a of args) {
      if (a.t === "range") {
        for (const addr of rangeAddrs(a.from, a.to)) {
          const e = onRange(lookup(addr));
          if (e !== undefined) return e;
        }
      } else {
        const e = onDirect(ev(a));
        if (e !== undefined) return e;
      }
    }
  }

  function numbers(args) {
    const nums = [];
    const err = eachArg(
      args,
      (v) => { if (isErr(v)) return v; if (typeof v === "number") nums.push(v); },
      (v) => { const x = toNum(v); if (isErr(x)) return x; nums.push(x); },
    );
    return err !== undefined ? err : nums;
  }

  function logicals(args) {
    const vals = [];
    const err = eachArg(
      args,
      (v) => { if (isErr(v)) return v; if (typeof v === "number" || typeof v === "boolean") vals.push(toBool(v)); },
      (v) => { const b = toBool(v); if (isErr(b)) return b; vals.push(b); },
    );
    return err !== undefined ? err : vals;
  }

  function call(n) {
    const { name, args } = n;
    const argc = args.length;
    const fixed = (min, max) => argc >= min && argc <= max;
    switch (name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": {
        const nums = numbers(args);
        if (!Array.isArray(nums)) return nums;
        if (name === "SUM") return finite(nums.reduce((s, x) => s + x, 0));
        if (name === "AVERAGE") return nums.length ? finite(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
        if (!nums.length) return 0;
        return nums.reduce((m, x) => (name === "MIN" ? Math.min(m, x) : Math.max(m, x)));
      }
      case "COUNT": {
        let c = 0;
        eachArg(args, (v) => { if (typeof v === "number") c++; }, (v) => { if (typeof v === "number") c++; });
        return c;
      }
      case "IF": {
        if (!fixed(2, 3)) return "#VALUE!";
        const c = toBool(ev(args[0]));
        if (isErr(c)) return c;
        if (c) return ev(args[1]);
        return argc === 3 ? ev(args[2]) : false;
      }
      case "AND": case "OR": {
        if (argc < 1) return "#VALUE!";
        const vals = logicals(args);
        if (!Array.isArray(vals)) return vals;
        if (!vals.length) return "#VALUE!";
        return name === "AND" ? vals.every(Boolean) : vals.some(Boolean);
      }
      case "NOT": {
        if (argc !== 1) return "#VALUE!";
        const b = toBool(ev(args[0]));
        return isErr(b) ? b : !b;
      }
      case "ROUND": {
        if (argc !== 2) return "#VALUE!";
        const x = toNum(ev(args[0]));
        if (isErr(x)) return x;
        const d = toNum(ev(args[1]));
        if (isErr(d)) return d;
        return finite(roundHalfAway(x, d));
      }
      case "ABS": {
        if (argc !== 1) return "#VALUE!";
        const x = toNum(ev(args[0]));
        return isErr(x) ? x : Math.abs(x);
      }
      case "LEN": case "UPPER": case "LOWER": {
        if (argc !== 1) return "#VALUE!";
        const v = ev(args[0]);
        if (isErr(v)) return v;
        const s = toText(v);
        return name === "LEN" ? s.length : name === "UPPER" ? s.toUpperCase() : s.toLowerCase();
      }
      case "CONCAT": {
        let out = "";
        const add = (v) => { if (isErr(v)) return v; out += toText(v); };
        const err = eachArg(args, add, add);
        return err !== undefined ? err : out;
      }
      default: return "#NAME?";
    }
  }

  return ev(ast);
}
