import { test } from "node:test";
import assert from "node:assert/strict";
import { parseFormula, refsOf, evaluate } from "../src/index.mjs";

const cells = { A1: 1, A2: 2, B1: "x", B2: null, C1: "#REF!" };
const run = (f) => evaluate(parseFormula(f), (a) => cells[a] ?? null);

test("operators and precedence", () => {
  assert.equal(run("-2^2"), 4);
  assert.equal(run("2^3^2"), 64);
  assert.equal(run('"a"&1+2&"b"'), "a3b");
  assert.equal(run('"abc"="ABC"'), true);
  assert.equal(run("1/0"), "#DIV/0!");
  assert.equal(run('"x"+1'), "#VALUE!");
  assert.equal(run("A1:A2"), "#VALUE!");
  assert.throws(() => parseFormula("1+"), SyntaxError);
});

test("functions", () => {
  assert.equal(run("sum(A1:B2, 3, TRUE)"), 7);
  assert.equal(run("COUNT(A1:B2, \"1\")"), 2);
  assert.equal(run("SUM(C1)"), "#REF!");
  assert.equal(run("IF(FALSE, 1/0)"), false);
  assert.equal(run("ROUND(-2.5, 0)"), -3);
  assert.equal(run("ROUND(1234, -2)"), 1200);
  assert.equal(run("CONCAT(A1:B2, \"!\")"), "1x2!");
  assert.equal(run("FOO(1)"), "#NAME?");
});

test("refsOf", () => {
  assert.deepEqual(refsOf(parseFormula("SUM($b$2:A1, a1) + C1")), ["B2", "A1", "B1", "A2", "C1"].filter((x) => x !== "A2" || true).sort(() => 0) && ["A1", "B1", "A2", "B2", "C1"]);
});
