import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr } from "./addr.mjs";

export function valueOf(raw) {
  if (raw === "") return null;
  const t = raw.trim();
  if (t !== "" && Number.isFinite(Number(t))) return Number(t);
  const u = t.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

// Parses every formula cell; returns Map addr -> { ast, refs } (ast null if unparsable).
function formulaGraph(sheet) {
  const g = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (!raw.startsWith("=")) continue;
    try {
      const ast = parseFormula(raw.slice(1));
      g.set(addr, { ast, refs: refsOf(ast).filter((r) => sheet.cells.get(r)?.startsWith("=")) });
    } catch {
      g.set(addr, { ast: null, refs: [] });
    }
  }
  return g;
}

// Iterative Tarjan; returns SCCs with dependencies before dependents.
function sccs(g) {
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [], out = [];
  let n = 0;
  for (const root of g.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, n); low.set(root, n++); stack.push(root); onStack.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const [v, i] = frame;
      const refs = g.get(v).refs;
      if (i < refs.length) {
        frame[1]++;
        const w = refs[i];
        if (!index.has(w)) {
          index.set(w, n); low.set(w, n++); stack.push(w); onStack.add(w);
          work.push([w, 0]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) {
          const p = work[work.length - 1][0];
          low.set(p, Math.min(low.get(p), low.get(v)));
        }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const onCycle = (g, comp) => comp.length > 1 || g.get(comp[0]).refs.includes(comp[0]);

export function computeAll(sheet) {
  const g = formulaGraph(sheet);
  const values = new Map();
  for (const [addr, raw] of sheet.cells) if (!g.has(addr)) values.set(addr, valueOf(raw));
  const lookup = (a) => values.get(a) ?? null;
  for (const comp of sccs(g)) {
    if (onCycle(g, comp)) { for (const a of comp) values.set(a, "#CYCLE!"); continue; }
    const { ast } = g.get(comp[0]);
    values.set(comp[0], ast ? evaluate(ast, lookup) : "#ERROR!");
  }
  const result = new Map();
  for (const addr of sheet.cells.keys()) result.set(addr, values.get(addr));
  return result;
}

export function dependents(sheet, addr) {
  const g = formulaGraph(sheet);
  const start = toAddr(parseAddr(addr).col, parseAddr(addr).row);
  const readers = new Map();
  for (const [a, { refs }] of g) for (const r of refs) (readers.get(r) ?? readers.set(r, []).get(r)).push(a);
  // Formula cells reading start are in g.refs only if start is a formula; add direct refs to non-formula start.
  for (const [a, { ast }] of g) {
    if (ast && !g.has(start) && refsOf(ast).includes(start)) (readers.get(start) ?? readers.set(start, []).get(start)).push(a);
  }
  const reach = new Set(), todo = [start];
  while (todo.length) for (const r of readers.get(todo.pop()) ?? []) if (!reach.has(r)) { reach.add(r); todo.push(r); }
  reach.delete(start);
  const cyc = new Set();
  for (const comp of sccs(g)) if (onCycle(g, comp)) for (const a of comp) cyc.add(a);
  const set = [...reach].filter((a) => !cyc.has(a));
  const inSet = new Set(set);
  const key = (a) => { const p = parseAddr(a); return p.row * 1e6 + p.col; };
  const indeg = new Map(), outs = new Map();
  for (const a of set) {
    const deps = new Set(g.get(a).refs.filter((r) => inSet.has(r) && r !== a));
    indeg.set(a, deps.size);
    for (const d of deps) (outs.get(d) ?? outs.set(d, []).get(d)).push(a);
  }
  const heap = [];
  const push = (a) => {
    heap.push(a);
    for (let i = heap.length - 1; i > 0;) {
      const p = (i - 1) >> 1;
      if (key(heap[p]) <= key(heap[i])) break;
      [heap[p], heap[i]] = [heap[i], heap[p]]; i = p;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      for (let i = 0; ;) {
        let m = i;
        for (const c of [2 * i + 1, 2 * i + 2]) if (c < heap.length && key(heap[c]) < key(heap[m])) m = c;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]]; i = m;
      }
    }
    return top;
  };
  for (const a of set) if (indeg.get(a) === 0) push(a);
  const order = [];
  while (heap.length) {
    const a = pop();
    order.push(a);
    for (const o of outs.get(a) ?? []) { indeg.set(o, indeg.get(o) - 1); if (indeg.get(o) === 0) push(o); }
  }
  return order;
}
