import { parseAddr, toAddr, colIndex } from "./addr.mjs";
import { valueOf } from "./recalc.mjs";

function parseRange(range) {
  const [a, b] = range.split(":");
  const p = parseAddr(a), q = parseAddr(b ?? a);
  return { c1: Math.min(p.col, q.col), c2: Math.max(p.col, q.col), r1: Math.min(p.row, q.row), r2: Math.max(p.row, q.row) };
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

// Orders non-empty values: numbers, strings (case-insensitive), booleans.
function compareValues(x, y) {
  const rx = rank(x), ry = rank(y);
  if (rx !== ry) return rx - ry;
  if (rx === 1) { x = x.toLowerCase(); y = y.toLowerCase(); }
  return x < y ? -1 : x > y ? 1 : 0;
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const first = options.header ? r1 + 1 : r1;
  const rows = [];
  for (let r = first; r <= r2; r++) {
    const raws = [];
    for (let c = c1; c <= c2; c++) raws.push(sheet.cells.get(toAddr(c, r)) ?? "");
    rows.push(raws);
  }
  const sorted = rows
    .map((raws) => ({ raws, vals: raws.map(valueOf) }))
    .sort((a, b) => {
      for (const { col, desc } of keys) {
        const i = colIndex(col) - c1;
        const x = a.vals[i], y = b.vals[i];
        if (x === null || y === null) { if (x === y) continue; return x === null ? 1 : -1; }
        const d = compareValues(x, y);
        if (d) return desc ? -d : d;
      }
      return 0;
    });
  sorted.forEach(({ raws }, k) => {
    raws.forEach((raw, i) => {
      const addr = toAddr(c1 + i, first + k);
      if (raw === "") sheet.cells.delete(addr); else sheet.cells.set(addr, raw);
    });
  });
}

