  for (let c = c1; c <= c2; c++) names.push(values.get(toAddr(c, r1)));
  const find = (name) => {
    const i = names.indexOf(name);
    if (i < 0) throw new Error(`no such column: ${name}`);
    return c1 + i;
  };
