  const BLANK = Symbol("blank");
  const groups = new Map();
  for (let r = r1 + 1; r <= r2; r++) {
    let k = values.get(toAddr(kc, r)) ?? BLANK;
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(values.get(toAddr(vc, r)) ?? null);
  }
  const aggregate = (vs) => {
    if (agg === "count") return vs.filter((v) => v !== null).length;
    const nums = vs.filter((v) => typeof v === "number");
    if (agg === "sum") return nums.reduce((s, v) => s + v, 0);
    if (!nums.length) return null;
    if (agg === "avg") return nums.reduce((s, v) => s + v, 0) / nums.length;
    if (agg === "min") return nums.reduce((m, v) => (v < m ? v : m));
    if (agg === "max") return nums.reduce((m, v) => (v > m ? v : m));
    throw new Error(`unknown aggregate: ${agg}`);
  };
  const keys = [...groups.keys()].filter((k) => k !== BLANK).sort(compareValues);
  const out = keys.map((key) => ({ key, value: aggregate(groups.get(key)) }));
  if (groups.has(BLANK)) out.push({ key: "(blank)", value: aggregate(groups.get(BLANK)) });
  return out;
}
