// Subset of spreadsheet number formats.

function splitSections(pattern) {
  const out = [];
  let cur = "";
  let quoted = false;
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (c === "\\" && !quoted) {
      cur += c + (pattern[++i] ?? "");
      continue;
    }
    if (c === '"') quoted = !quoted;
    if (c === ";" && !quoted) {
      out.push(cur);
      cur = "";
    } else cur += c;
  }
  out.push(cur);
  return out;
}

function tokenize(section) {
  const tokens = [];
  for (let i = 0; i < section.length; i++) {
    const c = section[i];
    if (c === '"') {
      const end = section.indexOf('"', i + 1);
      const stop = end < 0 ? section.length : end;
      tokens.push({ t: "lit", v: section.slice(i + 1, stop) });
      i = stop;
    } else if (c === "\\") {
      tokens.push({ t: "lit", v: section[++i] ?? "" });
    } else if (c === "0" || c === "#") tokens.push({ t: "ph", v: c });
    else if (c === ".") tokens.push({ t: "dot" });
    else if (c === ",") tokens.push({ t: "comma" });
    else if (c === "%") tokens.push({ t: "pct" });
    else if ((c === "E" || c === "e") && (section[i + 1] === "+" || section[i + 1] === "-")) {
      tokens.push({ t: "exp", plus: section[i + 1] === "+", v: c });
      i++;
    } else tokens.push({ t: "lit", v: c });
  }
  return tokens;
}

// Decimal string parts of a non-negative finite number as JS prints it.
function decimalParts(x) {
  const s = String(x);
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]\d+))?$/.exec(s);
  return shift(m[1], m[2] ?? "", m[3] ? Number(m[3]) : 0);
}

// Move the decimal point right by k places (left if negative).
function shift(int, frac, k) {
  const digits = int + frac;
  const p = int.length + k;
  let d = digits;
  let q = p;
  if (q < 0) {
    d = "0".repeat(-q) + d;
    q = 0;
  } else if (q > d.length) d += "0".repeat(q - d.length);
  return { int: d.slice(0, q).replace(/^0+/, ""), frac: d.slice(q) };
}

// Increment a digit string; may grow by one digit.
function increment(d) {
  const a = d.split("");
  let i = a.length - 1;
  while (i >= 0 && a[i] === "9") a[i--] = "0";
  if (i < 0) return "1" + a.join("");
  a[i] = String(Number(a[i]) + 1);
  return a.join("");
}

// Round half away from zero (on magnitude) to n decimals.
function roundDecimals({ int, frac }, n) {
  const f = frac.padEnd(n, "0");
  let digits = int + f.slice(0, n);
  if (f.length > n && f[n] >= "5") digits = increment(digits.padStart(1, "0"));
  const il = digits.length - n;
  return { int: digits.slice(0, il).replace(/^0+/, ""), frac: digits.slice(il) };
}

function isZero({ int, frac }) {
  return !/[1-9]/.test(int + frac);
}

function sci({ int, frac }, n) {
  let e;
  let digits;
  if (int) {
    e = int.length - 1;
    digits = int + frac;
  } else {
    const stripped = frac.replace(/^0+/, "");
    e = stripped ? -(frac.length - stripped.length + 1) : 0;
    digits = stripped;
  }
  digits = digits.padEnd(n + 1, "0");
  let head = digits.slice(0, n + 1);
  if (digits.length > n + 1 && digits[n + 1] >= "5") {
    head = increment(head);
    if (head.length > n + 1) {
      head = head.slice(0, n + 1);
      e++;
    }
  }
  return { mant: head[0], frac: head.slice(1), e };
}

function trimFrac(frac, phs) {
  const min = phs.lastIndexOf("0") + 1;
  let end = frac.length;
  while (end > min && frac[end - 1] === "0") end--;
  return frac.slice(0, end);
}

function render(tokens, num, negativeSign) {
  const hasExp = tokens.some((t) => t.t === "exp");
  const dotAt = tokens.findIndex((t) => t.t === "dot");
  const expAt = tokens.findIndex((t) => t.t === "exp");
  const intEnd = dotAt >= 0 ? dotAt : expAt >= 0 ? expAt : tokens.length;
  const fracEnd = expAt >= 0 ? expAt : tokens.length;
  const fracPhs = dotAt >= 0 ? tokens.slice(dotAt + 1, fracEnd).filter((t) => t.t === "ph").map((t) => t.v) : [];
  const n = fracPhs.length;
  const pcts = tokens.filter((t) => t.t === "pct").length;

  let d = decimalParts(num);
  if (pcts) d = shift(d.int, d.frac, 2 * pcts);

  let intStr;
  let fracStr;
  let expStr = "";
  if (hasExp) {
    const s = sci(d, n);
    const zero = isZero({ int: s.mant, frac: s.frac }) ;
    const e = zero ? 0 : s.e;
    intStr = s.mant;
    fracStr = s.frac;
    const minDigits = tokens.slice(expAt + 1).filter((t) => t.t === "ph" && t.v === "0").length;
    const sign = e < 0 ? "-" : tokens[expAt].plus ? "+" : "";
    expStr = tokens[expAt].v + sign + String(Math.abs(e)).padStart(minDigits, "0");
    d = { int: intStr.replace(/^0+/, ""), frac: fracStr };
  } else {
    d = roundDecimals(d, n);
    intStr = d.int;
    fracStr = d.frac;
  }
  fracStr = trimFrac(fracStr, fracPhs);

  const intPhs = tokens.slice(0, intEnd).filter((t) => t.t === "ph");
  const minInt = intPhs.filter((t) => t.v === "0").length;
  if (!hasExp) intStr = intStr.padStart(minInt, "0");
  else intStr = intStr || "0";

  const grouping = tokens.some((t, i) => {
    if (t.t !== "comma" || i >= intEnd) return false;
    return tokens.slice(0, i).some((x) => x.t === "ph") && tokens.slice(i + 1, intEnd).some((x) => x.t === "ph");
  });
  const digitAt = (pos) => intStr[intStr.length - 1 - pos] + (grouping && pos > 0 && pos % 3 === 0 ? "," : "");

  let k = intStr.length;
  const firstPh = tokens.findIndex((t) => t.t === "ph");
  let fi = 0;
  let out = "";
  let phase = "int";
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (i === expAt) {
      phase = "exp";
      out += expStr;
      continue;
    }
    if (phase === "exp") {
      if (t.t === "lit") out += t.v;
      continue;
    }
    if (t.t === "dot") {
      phase = "frac";
      out += ".";
    } else if (t.t === "pct") out += "%";
    else if (t.t === "lit") out += t.v;
    else if (t.t === "ph" && phase === "int") {
      // Placeholders to the right of this one in the integer part.
      const rest = tokens.slice(i + 1, intEnd).filter((x) => x.t === "ph").length;
      if (rest < k) {
        let s = "";
        const stop = i === firstPh ? 0 : rest;
        while (k > stop) s += digitAt(--k);
        out += s;
      } else if (rest === k) out += t.v === "0" ? "0" : "";
      else out += "";
    } else if (t.t === "ph") out += fracStr[fi++] ?? "";
  }
  const zero = isZero({ int: intStr, frac: fracStr });
  return { text: out, zero };
}

export function formatNumber(value, pattern) {
  if (typeof value !== "number") {
    if (value === null || value === undefined) return "";
    if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
    return String(value);
  }
  if (/^general$/i.test(pattern)) return String(value);
  if (!Number.isFinite(value)) return String(value);
  const sections = splitSections(pattern);
  const neg = value < 0;
  let section;
  let sign = false;
  if (sections.length === 1) {
    section = sections[0];
    sign = neg;
  } else if (neg) section = sections[1];
  else if (value === 0 && sections.length >= 3) section = sections[2];
  else section = sections[0];
  const { text, zero } = render(tokenize(section), Math.abs(value));
  return sign && !zero ? "-" + text : text;
}
