// Row and column insertion/deletion, rewriting formula references to follow the moved cells.
import { parseAddr, toAddr, colName, colIndex } from "./addr.mjs";

const REF = /(?<![A-Za-z0-9_.])(\$?[A-Za-z]{1,3}\$?\d+)(?::(\$?[A-Za-z]{1,3}\$?\d+))?(?![A-Za-z0-9_.(])/g;

// Maps one index; null when deleted.
function mapIndex(n, op) {
  if (op.kind === "insert") return n >= op.at ? n + op.count : n;
  if (n < op.at) return n;
  return n >= op.at + op.count ? n - op.count : null;
}

function mapRange(lo, hi, op) {
  if (op.kind === "insert") return [mapIndex(lo, op), hi >= op.at ? hi + op.count : hi];
  const end = op.at + op.count;
  if (lo >= op.at && hi < end) return null;
  const nlo = lo < op.at ? lo : lo >= end ? lo - op.count : op.at;
  const nhi = hi >= end ? hi - op.count : hi >= op.at ? op.at - 1 : hi;
  return [nlo, nhi];
}

const fmt = (a, col, row) => `${a.colAbs ? "$" : ""}${colName(col)}${a.rowAbs ? "$" : ""}${row + 1}`;

function rewriteRef(first, second, op) {
  const a = parseAddr(first);
  const axis = op.axis;
  if (!second) {
    const n = mapIndex(a[axis], op);
    if (n === null) return "#REF!";
    return fmt(a, axis === "col" ? n : a.col, axis === "row" ? n : a.row);
  }
  const b = parseAddr(second);
  const swap = a[axis] > b[axis];
  const [p, q] = swap ? [b, a] : [a, b];
  const r = mapRange(p[axis], q[axis], op);
  if (!r) return "#REF!";
  const np = { ...p, [axis]: r[0] }, nq = { ...q, [axis]: r[1] };
  const [x, y] = swap ? [nq, np] : [np, nq];
  return `${fmt(a, x.col, x.row)}:${fmt(b, y.col, y.row)}`;
}

export function rewriteFormula(raw, op) {
  return raw.split(/("(?:[^"]|"")*"?)/).map((part, i) =>
    i % 2 ? part : part.replace(REF, (_, f, s) => rewriteRef(f, s, op))).join("");
}

function apply(sheet, op) {
  const next = new Map();
  for (const [addr, raw] of sheet.cells) {
    const a = parseAddr(addr);
    const n = mapIndex(a[op.axis], op);
    if (n === null) continue;
    const col = op.axis === "col" ? n : a.col, row = op.axis === "row" ? n : a.row;
    next.set(toAddr(col, row), raw.startsWith("=") ? rewriteFormula(raw, op) : raw);
  }
  sheet.cells = next;
}

export const insertRows = (sheet, at, count = 1) => apply(sheet, { kind: "insert", axis: "row", at: at - 1, count });
export const deleteRows = (sheet, at, count = 1) => apply(sheet, { kind: "delete", axis: "row", at: at - 1, count });
export const insertCols = (sheet, at, count = 1) => apply(sheet, { kind: "insert", axis: "col", at: colIndex(at), count });
export const deleteCols = (sheet, at, count = 1) => apply(sheet, { kind: "delete", axis: "col", at: colIndex(at), count });
