// CSV import and export for sheets.
import { parseAddr, toAddr } from "./addr.mjs";
import { createSheet, setCell, getCell, cellAddrs } from "./sheet.mjs";

const valueText = (v) => (v === null || v === undefined ? "" : v === true ? "TRUE" : v === false ? "FALSE" : String(v));

const quote = (s) => (/[,"\n\r]/.test(s) || s.startsWith(" ") || s.endsWith(" ") ? `"${s.replace(/"/g, '""')}"` : s);

export function toCSV(sheet, values = null) {
  const addrs = cellAddrs(sheet);
  if (!addrs.length) return "";
  let rows = 0, cols = 0;
  for (const a of addrs) { const p = parseAddr(a); rows = Math.max(rows, p.row + 1); cols = Math.max(cols, p.col + 1); }
  let out = "";
  for (let r = 0; r < rows; r++) {
    const fields = [];
    for (let c = 0; c < cols; c++) {
      const addr = toAddr(c, r);
      fields.push(quote(values ? valueText(values.get(addr)) : getCell(sheet, addr)));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detectDelimiter(text) {
  const counts = { ",": 0, ";": 0, "\t": 0 };
  let inQ = false;
  for (const ch of text) {
    if (ch === '"') inQ = !inQ;
    else if (!inQ && (ch === "\n" || ch === "\r")) break;
    else if (!inQ && ch in counts) counts[ch]++;
  }
  let best = ",";
  for (const d of [";", "\t"]) if (counts[d] > counts[best]) best = d;
  return best;
}

export function fromCSV(text, options = {}) {
  const delim = options.delimiter ?? detectDelimiter(text);
  const sheet = createSheet();
  let row = 0, col = 0, field = "", line = 1, i = 0, pending = false;
  const endField = () => {
    if (field.startsWith("=") && !options.formulas) field = "'" + field;
    setCell(sheet, toAddr(col, row), field);
    field = ""; col++; pending = false;
  };
  while (i < text.length) {
    const ch = text[i];
    if (ch === '"' && field === "" && !pending) {
      const startLine = line;
      i++;
      for (;;) {
        if (i >= text.length) throw new Error(`unclosed quote at line ${startLine}`);
        const c = text[i];
        if (c === '"') {
          if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
          i++; break;
        }
        if (c === "\n") line++;
        field += c; i++;
      }
      pending = true;
    } else if (ch === delim) {
      endField(); i++; pending = true;
    } else if (ch === "\n" || ch === "\r") {
      if (ch === "\r" && text[i + 1] === "\n") i++;
      i++; line++;
      endField(); row++; col = 0; pending = false;
    } else { field += ch; i++; pending = true; }
  }
  if (pending || field !== "") endField();
  return sheet;
}
